import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.chrome.ChromeDriver;
import org.testng.Assert;
import org.testng.annotations.*;
import java.io.File;

public class FoodOrderingTest {
    WebDriver driver;

    @BeforeClass
    public void setup() {
        driver = new ChromeDriver();
        driver.get(new File("index.html").toURI().toString());
    }

    @Test(priority = 1)
    public void testAddToCart() {
        // Clicks the first "Add to Cart" button generated by displayFoods()
        WebElement firstAddBtn = driver.findElement(By.xpath("//button[contains(text(),'Add')]"));
        firstAddBtn.click();

        // Checks that cart-count in your header updated from 0 to 1
        String count = driver.findElement(By.id("cart-count")).getText();
        Assert.assertEquals(count, "1");
    }

    @Test(priority = 2)
    public void testPlaceOrder() {
        // Clicks the button that triggers checkout()
        WebElement checkoutBtn = driver.findElement(By.xpath("//button[@onclick='checkout()']"));
        checkoutBtn.click();

        // Matches id="order-message" and exact text from your script.js
        String msg = driver.findElement(By.id("order-message")).getText();
        Assert.assertEquals(msg, "Your order has been placed successfully!");
    }

    @AfterClass
    public void teardown() {
        if (driver != null) {
            driver.quit();
        }
    }
}